488	<script>
489	(function() {
490		// Tab switching.
491		const nav   = document.getElementById('mcp-tab-nav');
492		const panels = document.querySelectorAll('.mcp-tab-panel');
493	
494		nav.querySelectorAll('a').forEach(function(link) {
495			link.addEventListener('click', function(e) {
496				e.preventDefault();
497				nav.querySelectorAll('a').forEach(function(a) { a.classList.remove('active'); });
498				panels.forEach(function(p) { p.classList.remove('active'); });
499				link.classList.add('active');
500				document.querySelector(link.getAttribute('href')).classList.add('active');
501			});
502		});
503	
504		// Copy to clipboard.
505		function copyText(text, btn) {
506			navigator.clipboard.writeText(text).then(function() {
507				var orig = btn.textContent;
508				btn.textContent = '✓ Copied!';
509				setTimeout(function() { btn.textContent = orig; }, 2000);
510			});
511		}
512	
513		document.querySelectorAll('.mcp-copy-btn').forEach(function(btn) {
514			btn.addEventListener('click', function() {
515				var target = document.querySelector(btn.getAttribute('data-clipboard-target'));
516				if (target) { copyText(target.textContent.trim(), btn); }
517			});
518		});
519	
520		document.querySelectorAll('.mcp-copy-code-btn').forEach(function(btn) {
521			btn.addEventListener('click', function() {
522				copyText(btn.getAttribute('data-clipboard-code'), btn);
523			});
524		});
525	
526		// Detect user OS.
527		function detectOS() {
528			var ua = navigator.userAgent;
529			if (ua.indexOf('Win') !== -1) return 'windows';
530			if (ua.indexOf('Mac') !== -1) return 'macos';
531			if (ua.indexOf('Linux') !== -1) return 'linux';
532			return 'macos';
533		}
534	
535		// OS button switching.
536		function setupOSButtons(pathSelector) {
537			var pathEl = document.querySelector(pathSelector);
538			if (!pathEl) return;
539			var card = pathEl.closest('.mcp-setup-card');
540			var buttons = card.querySelectorAll('.mcp-os-btn');
541			var detectedOS = detectOS();
542			var activeOS = detectedOS;
543	
544			// Set initial active state.
545			buttons.forEach(function(btn) {
546				if (btn.dataset.os === activeOS) {
547					btn.classList.add('active');
548					pathEl.textContent = btn.dataset.path;
549				}
550			});
551	
552			// Handle button clicks.
553			buttons.forEach(function(btn) {
554				btn.addEventListener('click', function() {
555					buttons.forEach(function(b) { b.classList.remove('active'); });
556					btn.classList.add('active');
557					pathEl.textContent = btn.dataset.path;
558				});
559			});
560		}
561	
562		// Initialize OS buttons for Claude and Cursor.
563		setupOSButtons('.mcp-claude-path');
564		setupOSButtons('.mcp-cursor-path');
565	})();
566	</script>
